SELECT * FROM daily_resource_stats 
WHERE tenant_id = #{tenantId} 
AND stat_date BETWEEN #{startDate} AND #{endDate}
ORDER BY stat_date, resource_id

SELECT COUNT(DISTINCT resource_id) FROM daily_resource_stats 
WHERE tenant_id = #{tenantId} AND stat_date BETWEEN #{startDate} AND #{endDate}
AND order_count > 0
